212				}
213				if !errors.Is(err, ErrLogRead) {
214					t.Fatalf("error must match ErrLogRead, got %v", err)
215				}
216				if !errors.Is(err, errSimulatedRead) {
217					t.Fatalf("underlying read cause must stay reachable, got %v", err)
218				}
