1	package relayproof
2	
3	// Regression coverage for an input source that makes no progress the way a
4	// stuck reader does: Read keeps returning (0, nil) — no bytes, no EOF, no
5	// error. A short run of such answers is tolerated (a source may briefly
6	// have nothing ready), but it must not be waited on forever: the 101st
7	// consecutive zero-byte, nil-error Read ends the run as an input-stream
8	// fault. The fixed contract asserted here:
9	//
10	//   - the returned error is non-nil and errors.Is matches BOTH ErrLogRead
11	//     and io.ErrNoProgress, while never matching ErrLogWrite, so the stall
12	//     can never look like normal completion, a single bad log line, or an
13	//     output fault;
14	//   - reading stops at the Read call that reaches the limit: a log the
15	//     source could deliver afterwards is never read or emitted, and a stall
16	//     never fabricates a failure record of its own — with no complete line
17	//     processed the failure count is zero despite the non-nil error;
18	//   - complete lines already processed survive untouched (valid logs keep
19	//     their events, invalid logs keep physical line number and reason,
20	//     blank lines only occupy a number), the failure count covers only
21	//     lines that failed normalization, and results are neither lost nor
22	//     duplicated;
23	//   - bytes received without a terminating newline stay an unfinished read
24	//     even when they are already a complete, field-valid JSON object: the
25	//     stall neither emits them as a final line nor counts them;
26	//   - the streak is CONSECUTIVE: 100 empty reads followed by bytes resume
27	//     normally, and ANY non-empty delivery — even a single byte that does
28	//     not complete a line — restarts the count, so several sub-limit empty
29	//     stretches interleaved with log fragments never accumulate into an
30	//     early failure; at a later clean EOF the newline-less final line is
31	//     still emitted under the existing rule.
32	//
33	// Every scenario is scripted in-process with scriptReader from
34	// normalize_io_test.go, so the boundary reproduces deterministically
35	// offline without real pipes, networks, timers, or device failures.
36	
37	import (
38		"bytes"
39		"errors"
40		"fmt"
41		"io"
42		"testing"
43	)
44	
45	// emptyReadSteps returns n scripted Read calls that deliver no bytes and
46	// report no error: the exact answer a wedged source gives while it neither
47	// produces data nor admits failure.
48	func emptyReadSteps(n int) []scriptStep {
49		return make([]scriptStep, n)
50	}
51	
52	// stalledTail is a valid log the source only becomes able to deliver
53	// AFTER the stall limit. A run that stops on time must leave this step
54	// unread; if it is consumed or emitted the run read past the fault.
55	func stalledTail() scriptStep {
56		return scriptStep{data: []byte(validLog("delivered-after-stall") + "\n")}
57	}
58	
59	// assertStallFault checks the public shape of a stalled-read return: a
60	// non-nil error recognizable as both ErrLogRead and io.ErrNoProgress, never
61	// as ErrLogWrite, carrying the progress-failure wording.
62	func assertStallFault(t *testing.T, err error) {
63		t.Helper()
64		if err == nil {
65			t.Fatalf("101 consecutive (0, nil) Reads must be a stream fault, got normal completion")
66		}
67		if !errors.Is(err, ErrLogRead) {
68			t.Fatalf("stall must be reported as an input-stream fault (ErrLogRead), got %v", err)
69		}
70		if !errors.Is(err, io.ErrNoProgress) {
71			t.Fatalf("caller must recognize the stall via io.ErrNoProgress, got %v", err)
72		}
73		if errors.Is(err, ErrLogWrite) {
74			t.Fatalf("a stall with a healthy writer must not be classified as a write fault: %v", err)
75		}
76		if !bytes.Contains([]byte(err.Error()), []byte(io.ErrNoProgress.Error())) {
77			t.Fatalf("error text must explain the lack of progress, got %q", err.Error())
78		}
79	}
80	
81	// With no complete line ever delivered, 101 consecutive empty reads are a
82	// fault that reports zero failed logs and writes nothing: the stall must
83	// not masquerade as a successful empty stream nor as one bad log line.
84	func TestNormalizeIOStallBeforeAnyLine(t *testing.T) {
85		steps := append(emptyReadSteps(101), stalledTail())
86		src := &scriptReader{steps: steps}
87		var out bytes.Buffer
88		failures, err := NormalizeReader(src, &out)
89		assertStallFault(t, err)
90		if failures != 0 {
91			t.Fatalf("no complete log was processed, so the failure count must be 0, got %d", failures)
92		}
93		if out.Len() != 0 {
94			t.Fatalf("a stall with no complete line must emit no record, got %q", out.String())
95		}
96		if src.i != 101 {
97			t.Fatalf("reading must stop at the 101st empty Read, consumed %d of %d scripted steps", src.i, len(steps))
98		}
99		if bytes.Contains(out.Bytes(), []byte("delivered-after-stall")) {
100			t.Fatalf("logs appearing only after the stall must never be emitted: %q", out.String())
101		}
102	}
103	
104	// A complete, field-valid JSON object already received WITHOUT a trailing
105	// newline is still an unfinished read when the source stalls: it must
106	// neither become the final result nor count as a failure, even though at a
107	// clean EOF the same bytes would be accepted as the last line.
108	func TestNormalizeIOStallKeepsPendingFragmentUnfinished(t *testing.T) {
109		fragment := `{"timestamp":"2026-01-02T00:00:00Z","action":"stalled-pending-fragment"}`
110		steps := append([]scriptStep{{data: []byte(fragment)}}, emptyReadSteps(101)...)
111		steps = append(steps, stalledTail())
112		src := &scriptReader{steps: steps}
113		var out bytes.Buffer
114		failures, err := NormalizeReader(src, &out)
115		assertStallFault(t, err)
116		if failures != 0 {
117			t.Fatalf("the newline-less pending object is not a processed log, failures must be 0, got %d", failures)
118		}
119		if out.Len() != 0 {
120			t.Fatalf("the pending object must not be finalized as a last line on a stall, got %q", out.String())
121		}
122		if src.i != 102 {
123			t.Fatalf("run must stop on the 101st empty Read after the fragment, consumed %d of %d steps", src.i, len(steps))
124		}
125	}
126	
127	// Complete lines already in hand when the source stalls must survive
128	// exactly as a healthy read of the same prefix would leave them: a valid
129	// log keeps its event, a blank line only reserves its physical number, an
130	// invalid log keeps that number and its reason and is the only counted
131	// failure, and nothing is lost, repeated, or reordered. The pending
132	// newline-less object (valid JSON) stays out, and the source is not read
133	// again after the limit is reached.
134	func TestNormalizeIOStallPreservesProcessedResults(t *testing.T) {
135		complete, fragment := mixedCompleteLinesAndFragment()
136		steps := []scriptStep{
137			{data: []byte(complete)},
138			{data: []byte(fragment)}, // newline-less valid object, left unfinished
139		}
140		steps = append(steps, emptyReadSteps(101)...)
141		steps = append(steps, stalledTail())
142		src := &scriptReader{steps: steps}
143		var out bytes.Buffer
144		failures, err := NormalizeReader(src, &out)
145		assertStallFault(t, err)
146		if failures != 1 {
147			t.Fatalf("only the one invalid complete line counts, got %d failures", failures)
148		}
149		if src.i != 103 {
150			t.Fatalf("processing must stop at the 101st empty Read (2 data Reads + 101), consumed %d of %d steps", src.i, len(steps))
151		}
152	
153		// Output must be byte-for-byte the healthy prefix: two whole records in
154		// physical order with no fabricated stall record and no duplication.
155		var healthy bytes.Buffer
156		healthyFailures, healthyErr := NormalizeReader(bytes.NewReader([]byte(complete)), &healthy)
157		if healthyErr != nil || healthyFailures != 1 {
158			t.Fatalf("test setup: healthy reference read failed: failures=%d err=%v", healthyFailures, healthyErr)
159		}
160		if !bytes.Equal(out.Bytes(), healthy.Bytes()) {
161			t.Fatalf("stall output must equal a healthy read of the complete prefix:\nstall:   %q\nhealthy: %q", out.String(), healthy.String())
162		}
163	
164		results := decodeResults(t, out.Bytes())
165		if len(results) != 2 {
166			t.Fatalf("the valid log and the invalid log each appear exactly once, got %#v", results)
167		}
168		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
169			t.Fatalf("line 1 must survive as a valid event: %#v", results[0])
170		}
171		if eventOf(t, results[0])["action"] != "a" {
172			t.Fatalf("line 1 content/order mismatch: %#v", results[0])
173		}
174		if results[1]["line"] != float64(3) || results[1]["ok"] != false {
175			t.Fatalf("blank line 2 only reserves a number, so the invalid log stays line 3: %#v", results[1])
176		}
177		if msg, _ := results[1]["error"].(string); msg == "" || !bytes.Contains([]byte(msg), []byte(FieldTimestamp)) {
178			t.Fatalf("invalid line must keep its concrete reason, got %q", msg)
179		}
180		if bytes.Contains(out.Bytes(), []byte("tail-fragment")) {
181			t.Fatalf("the pending newline-less object must not be finalized on a stall: %q", out.String())
182		}
183		if bytes.Contains(out.Bytes(), []byte("delivered-after-stall")) {
184			t.Fatalf("input appearing only after the stall must never be read or emitted: %q", out.String())
185		}
186	}
187	
188	// Exactly 100 consecutive empty reads sit at the tolerated boundary: bytes
189	// arriving on the next call resume normal processing, whether the empty
190	// stretch comes before the first log or between two logs. The final
191	// newline-less line is still finalized normally at EOF.
192	func TestNormalizeIOStallHundredEmptyReadsStillRecover(t *testing.T) {
193		steps := emptyReadSteps(100)
194		steps = append(steps,
195			scriptStep{data: []byte(validLog("a") + "\n")},
196		)
197		steps = append(steps, emptyReadSteps(100)...)
198		steps = append(steps,
199			scriptStep{data: []byte(validLog("b"))}, // no trailing newline
200			scriptStep{err: io.EOF},
201		)
202		src := &scriptReader{steps: steps}
203		var out bytes.Buffer
204		failures, err := NormalizeReader(src, &out)
205		if err != nil {
206			t.Fatalf("two runs of exactly 100 tolerated empty reads must end normally, got %v", err)
207		}
208		if failures != 0 {
209			t.Fatalf("all logs valid, got %d failures", failures)
210		}
211		if src.i != len(steps) {
212			t.Fatalf("recovery must consume the whole scripted stream, read %d of %d steps", src.i, len(steps))
213		}
214		results := decodeResults(t, out.Bytes())
215		if len(results) != 2 {
216			t.Fatalf("both logs around the empty stretches must be emitted, got %#v", results)
217		}
218		if results[0]["line"] != float64(1) || results[1]["line"] != float64(2) {
219			t.Fatalf("physical line numbers must be unaffected by empty reads: %#v", results)
220		}
221		if eventOf(t, results[1])["action"] != "b" {
222			t.Fatalf("the newline-less final line must finalize normally after recovery: %#v", results[1])
223		}
224	}
225	
226	// ANY non-empty delivery ends the consecutive-empty streak, even a single
227	// byte that does not complete a log line: 100 empties, then one '{', then
228	// 101 more empties must trip only the SECOND streak, and the lone byte must
229	// never become output. The scripted step after the trip stays unread.
230	func TestNormalizeIOStallSingleByteRestartsCounting(t *testing.T) {
231		steps := []scriptStep{{data: []byte(validLog("a") + "\n")}}
232		steps = append(steps, emptyReadSteps(100)...)
233		steps = append(steps, scriptStep{data: []byte("{")}) // one byte, no newline
234		steps = append(steps, emptyReadSteps(101)...)
235		steps = append(steps, stalledTail())
236		src := &scriptReader{steps: steps}
237		var out bytes.Buffer
238		failures, err := NormalizeReader(src, &out)
239		assertStallFault(t, err)
240		if failures != 0 {
241			t.Fatalf("the lone byte never completed a log; failures must be 0, got %d", failures)
242		}
243		// 1 data Read + 100 + 1 byte + 101 empties = 203; the post-stall step
244		// must remain unread. Stopping earlier (on the first streak) or later
245		// (reading past the trip) fails this position check.
246		wantReads := 1 + 100 + 1 + 101
247		if src.i != wantReads {
248			t.Fatalf("the second 101-empty streak must trip at Read %d, consumed %d of %d steps", wantReads, src.i, len(steps))
249		}
250		results := decodeResults(t, out.Bytes())
251		if len(results) != 1 || results[0]["ok"] != true {
252			t.Fatalf("only the complete log before the streaks may be emitted, got %#v", results)
253		}
254		if eventOf(t, results[0])["action"] != "a" {
255			t.Fatalf("surviving record content mismatch: %#v", results[0])
256		}
257		if bytes.Contains(out.Bytes(), []byte("delivered-after-stall")) {
258			t.Fatalf("input delivered after the trip must not be read: %q", out.String())
259		}
260	}
261	
262	// Several empty stretches, each below the limit and separated by fragments
263	// of one log line, must not accumulate into a failure: counting is per
264	// consecutive streak, not cumulative. The line fragments only reunite at a
265	// clean EOF, where the newline-less final log is emitted under the existing
266	// final-line rule.
267	func TestNormalizeIOStallSubLimitStretchesDoNotAccumulate(t *testing.T) {
268		line := validLog("seg-tail")
269		if len(line) < 30 {
270			t.Fatalf("test setup: fragment split point out of range")
271		}
272		first, rest := line[:25], line[25:]
273		steps := []scriptStep{{data: []byte(validLog("a") + "\n")}}
274		steps = append(steps, emptyReadSteps(99)...)
275		steps = append(steps, scriptStep{data: []byte(first)}) // no newline yet
276		steps = append(steps, emptyReadSteps(99)...)
277		steps = append(steps, scriptStep{data: []byte(rest)}) // completes the object, still no newline
278		steps = append(steps, emptyReadSteps(99)...)
279		steps = append(steps, scriptStep{err: io.EOF})
280		src := &scriptReader{steps: steps}
281		var out bytes.Buffer
282		failures, err := NormalizeReader(src, &out)
283		if err != nil {
284			t.Fatalf("three sub-limit empty stretches (297 empty reads in total) must not fail, got %v", err)
285		}
286		if failures != 0 {
287			t.Fatalf("all logs valid, got %d failures", failures)
288		}
289		if src.i != len(steps) {
290			t.Fatalf("a healthy stream must be read to its EOF step, read %d of %d", src.i, len(steps))
291		}
292		results := decodeResults(t, out.Bytes())
293		if len(results) != 2 {
294			t.Fatalf("the fragmented final log must reassemble into one record, got %#v", results)
295		}
296		if results[0]["line"] != float64(1) || results[1]["line"] != float64(2) || results[1]["ok"] != true {
297			t.Fatalf("both logs must appear once with correct physical numbers: %#v", results)
298		}
299		if eventOf(t, results[1])["action"] != "seg-tail" {
300			t.Fatalf("fragments reunited at EOF must produce the intended final event, got %#v", results[1])
301		}
302	}
303	
304	// Sanity guard for the scripting itself: the threshold the contract names is
305	// 101 consecutive empty reads, so 101 is the smallest number that faults.
306	// This keeps the other tests' counts honest if the bound is ever adjusted.
307	func TestNormalizeIOStallThresholdIsDocumentedBoundary(t *testing.T) {
308		for _, n := range []int{101, 102} {
309			t.Run(fmt.Sprintf("%d empty reads", n), func(t *testing.T) {
310				src := &scriptReader{steps: emptyReadSteps(n)}
311				failures, err := NormalizeReader(src, &bytes.Buffer{})
312				if err == nil || !errors.Is(err, ErrLogRead) || !errors.Is(err, io.ErrNoProgress) {
313					t.Fatalf("%d consecutive empty reads must be a stall fault, got failures=%d err=%v", n, failures, err)
314				}
315				if src.i != 101 {
316					t.Fatalf("must stop exactly on the 101st empty Read regardless of script length, consumed %d", src.i)
317				}
318			})
319		}
320	}
