345					}
346				}
347				if tc.wantResults == 1 && eventOf(t, last)["action"] != "head" {
348					t.Fatalf("dropped tail must leave the head record untouched: %#v", last)
349				}
350			})
351		}
352	}
353	
354	// A read fault that delivers only part of the stream must not turn the
355	// unterminated fragment into a record or a failure, no matter how the
356	// complete lines before it were chunked. The emitted prefix equals a
357	// healthy filtered read of exactly the complete lines, and the caller still
358	// receives ErrLogRead wrapping the original cause.
359	func TestNormalizeFilteredChunkedPartialReadFault(t *testing.T) {
360		filter := mustSourceFilter(t, "192.0.2.0/24")
361		complete := strings.Join([]string{
362			`{"timestamp":"2026-01-02T00:00:00Z","action":"in-allowed","source_ip":"192.0.2.7"}`,
363			`{"timestamp":"2026-01-02T00:00:00Z","action":"out-dropped","source_ip":"198.51.100.9"}`,
364			``,
365			`{"timestamp":"not-a-time","action":"bad-time-outside","source_ip":"198.51.100.30"}`,
366		}, "\n") + "\n"
367		fragments := []struct {
368			name     string
369			fragment string
370			marker   string
371		}{
372			{"fragment is a complete admittable object", `{"timestamp":"2026-01-02T00:00:00Z","action":"tail-in-allowed","source_ip":"192.0.2.7"}`, "tail-in-allowed"},
373			{"fragment carries an invalid timestamp", `{"timestamp":"not-a-time","action":"tail-bad-time","source_ip":"192.0.2.7"}`, "tail-bad-time"},
374		}
375		patterns := [][]int{{1}, {7, 4096, 3, 64}, {len(complete)}}
376	
377		var healthy bytes.Buffer
378		healthyFailures, healthyErr := NormalizeReaderFiltered(strings.NewReader(complete), &healthy, filter)
379		if healthyErr != nil || healthyFailures != 1 {
380			t.Fatalf("test setup: healthy reference read failed: failures=%d err=%v", healthyFailures, healthyErr)
381		}
382	
383		for _, tc := range fragments {
384			for pi, sizes := range patterns {
385				t.Run(fmt.Sprintf("%s/chunk pattern %d", tc.name, pi), func(t *testing.T) {
386					// Deliver the complete lines in the chunk pattern, then the
387					// unterminated fragment together with the read fault.
388					var steps []scriptStep
389					for pos, step := 0, 0; pos < len(complete); step++ {
390						n := sizes[step%len(sizes)]
391						if n <= 0 {
392							continue
393						}
394						if rem := len(complete) - pos; n > rem {
395							n = rem
396						}
397						steps = append(steps, scriptStep{data: []byte(complete[pos : pos+n])})
398						pos += n
399					}
400					steps = append(steps, scriptStep{data: []byte(tc.fragment), err: errSimulatedRead})
401	
402					var out bytes.Buffer
403					failures, err := NormalizeReaderFiltered(&scriptReader{steps: steps}, &out, filter)
404					if !errors.Is(err, ErrLogRead) || !errors.Is(err, errSimulatedRead) {
405						t.Fatalf("want ErrLogRead wrapping the read cause, got %v", err)
406					}
407					if failures != healthyFailures {
408						t.Fatalf("the failed-read fragment must not add failures: got %d, want %d", failures, healthyFailures)
409					}
410					if !bytes.Equal(out.Bytes(), healthy.Bytes()) {
411						t.Fatalf("output must equal a healthy filtered read of the complete lines:\nfault:   %q\nhealthy: %q", out.String(), healthy.String())
412					}
413					if bytes.Contains(out.Bytes(), []byte(tc.marker)) {
414						t.Fatalf("the unterminated fragment belongs to the failed read and must leave no record: %q", out.String())
415					}
416				})
417			}
418		}
419	}
